css:
.finder-page { --finder-ink: #39383d; --finder-muted: #88858b; --finder-line: #dddadd; --finder-side: #f1f1f2; --finder-paper: #fcfbfb; --finder-pink: #f6d8e2; --finder-pink-deep: #eec2d0; min-height: 100%; padding: 58px 28px; background: #fff; color: var(--finder-ink); font-family: Pretendard, -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', 'Noto Sans KR', sans-serif; font-size: 13px; line-height: 1.65; letter-spacing: -0.015em; }
.finder-page *, .finder-page *::before, .finder-page *::after { box-sizing: border-box; }
.finder-window { width: min(1000px, 100%); min-height: 620px; margin: 0 auto; overflow: hidden; border: 1px solid rgba(70, 66, 70, .14); border-radius: 18px; background: var(--finder-paper); box-shadow: 0 18px 38px rgba(65, 68, 60, .13); }
.finder-bar { display: grid; grid-template-columns: 120px minmax(0, 1fr) 120px; align-items: center; min-height: 49px; padding: 0 20px; border-bottom: 1px solid var(--finder-line); background: #f6f5f5; }
.finder-dots { display: flex; gap: 9px; align-items: center; }
.finder-dots span, .finder-back-button, .finder-home-button { display: block; width: 12px; height: 12px; border-radius: 50%; }
.finder-back-button { color: #fff; background: #f36a6a; font-size: 11px; font-weight: 700; line-height: 11px; text-align: center; text-decoration: none; }
.finder-back-button:hover { background: #df5555; }
.finder-dots span { background: #f5bf55; }
.finder-home-button { background: #70c879; text-decoration: none; }
.finder-home-button:hover { background: #59ae62; }
.finder-brand { min-width: 0; color: var(--finder-ink); font-size: 12px; font-weight: 700; letter-spacing: .02em; text-align: center; text-decoration: none; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.finder-bar-actions { display: flex; justify-content: flex-end; align-items: center; gap: 9px; min-width: 0; }
.finder-bar-note { color: var(--finder-muted); font-size: 9px; letter-spacing: .14em; text-align: right; }
.finder-layout { display: grid; grid-template-columns: 245px minmax(0, 1fr); min-height: 570px; }
.finder-sidebar { background: var(--finder-side); border-right: 1px solid var(--finder-line); padding: 30px 22px; }
.finder-profile { position: relative; display: flex; gap: 12px; align-items: center; padding: 0 4px 24px; border-bottom: 1px solid var(--finder-line); }
.finder-avatar { display: block; flex: 0 0 auto; width: 48px; height: 48px; border: 1px solid #d1ced1; border-radius: 50%; background: #e6e4e5; object-fit: cover; }
.finder-avatar:not([src]) { color: transparent; }
.finder-name { margin: 0 0 2px; font-size: 12px; font-weight: 700; }
.finder-bio { margin: 0; color: var(--finder-muted); font-size: 10px; line-height: 1.55; overflow-wrap: anywhere; }
.finder-owner-links { position: absolute; right: 4px; bottom: 24px; display: flex; gap: 7px; margin: 0; padding: 0; color: var(--finder-muted); font-size: 9px; letter-spacing: .1em; white-space: nowrap; }
.finder-owner-links a { color: inherit; text-decoration: none; }
.finder-owner-links a:hover { color: var(--finder-ink); text-decoration: underline; text-underline-offset: 3px; }
.finder-nav { padding-top: 22px; }
.finder-home, .finder-nav-list a { color: #55535a; text-decoration: none; }
.finder-home { display: block; margin: 0 0 19px; padding: 6px 8px; border-radius: 4px; font-size: 11px; font-weight: 700; letter-spacing: .08em; }
.finder-home::before, .finder-nav-list a::before { display: inline-block; width: 16px; margin-right: 7px; color: #9cbfe3; content: '◉'; font-size: 10px; text-align: center; }
.finder-nav-group + .finder-nav-group { margin-top: 22px; }
.finder-nav-label { margin: 0 0 5px; padding: 0 8px; color: var(--finder-muted); font-size: 9px; font-weight: 700; letter-spacing: .12em; }
.finder-nav-list { margin: 0; padding: 0; list-style: none; }
.finder-nav-list a { display: block; padding: 6px 8px; border-radius: 4px; font-size: 11px; overflow-wrap: anywhere; }
.finder-nav-list a::before { content: '▰'; color: #9fc4e7; }
.finder-home:hover, .finder-nav-list a:hover { background: #e4e2e4; color: var(--finder-ink); }
.finder-main { min-width: 0; padding: 49px 54px 60px; background: var(--finder-paper); }
.finder-home-main { display: flex; align-items: center; justify-content: center; }
.finder-home-feature { width: min(360px, 100%); margin: 0; text-align: center; }
.finder-home-image { display: block; width: 100%; max-width: 100%; height: auto; aspect-ratio: 1 / 1; border: 0; border-radius: 3px; background: #e6e4e5; object-fit: cover; }
.finder-home-text { min-height: 20px; margin-top: 12px; color: var(--finder-muted); background: #fff; font-size: 11px; line-height: 1.65; text-align: left; overflow-wrap: anywhere; }
.finder-content-head { display: flex; align-items: end; justify-content: space-between; gap: 20px; margin-bottom: 34px; }
.finder-kicker { margin: 0 0 2px; color: #b4afb4; font-size: 11px; letter-spacing: .02em; }
.finder-content-head h1 { margin: 0; color: #29272c; font-size: 34px; font-weight: 700; line-height: 1.18; letter-spacing: -.045em; overflow-wrap: anywhere; }
.finder-count { margin: 0 0 3px; color: var(--finder-muted); font-size: 9px; letter-spacing: .12em; }
.finder-actions { display: flex; gap: 8px; margin: 0 0 2px; }
.finder-actions a { color: var(--finder-muted); font-size: 9px; letter-spacing: .09em; text-decoration: none; }
.finder-actions a:hover { color: var(--finder-ink); text-decoration: underline; text-underline-offset: 3px; }
.finder-post-grid, .finder-banner-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 31px 26px; margin: 0; padding: 0; list-style: none; }
.finder-banner-grid { grid-template-columns: minmax(0, 1fr); gap: 12px; }
.finder-post-card, .finder-banner-card { min-width: 0; }
.finder-post-card a, .finder-banner-card a { display: flex; flex-direction: column; align-items: center; min-width: 0; color: var(--finder-ink); text-align: center; text-decoration: none; }
.finder-folder { position: relative; display: block; width: 118px; max-width: 100%; height: 84px; margin-bottom: 10px; border: 1px solid #edcbd6; border-radius: 3px 3px 1px 1px; background: var(--finder-pink); box-shadow: inset 0 10px 0 rgba(255,255,255,.17); }
.finder-folder::before { position: absolute; top: -7px; left: 0; width: 42%; height: 10px; border: 1px solid #edcbd6; border-bottom: 0; border-radius: 6px 8px 0 0; background: var(--finder-pink-deep); content: ''; }
.finder-post-category { max-width: 100%; margin-bottom: 1px; color: #ab8996; font-size: 9px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.finder-post-card strong, .finder-banner-card strong { display: block; max-width: 100%; font-size: 12px; font-weight: 500; line-height: 1.45; overflow-wrap: anywhere; }
.finder-post-card small { margin-top: 3px; color: var(--finder-muted); font-size: 9px; }
.finder-lock { margin-top: 4px; padding: 1px 5px; border: 1px solid #e1cbd2; color: #ae7f8c; font-size: 8px; letter-spacing: .08em; }
.finder-post-card a:hover .finder-folder { background: #f2cbd8; }
.finder-post-card a:hover strong, .finder-banner-card a:hover strong { text-decoration: underline; text-underline-offset: 3px; }
.finder-post-grid:empty::after, .finder-banner-grid:empty::after { grid-column: 1 / -1; padding: 35px 0; color: var(--finder-muted); font-size: 11px; content: '비어 있는 폴더입니다.'; }
.finder-banner-card a { position: relative; }
.finder-banner-card img { display: block; width: 80%; max-width: 100%; height: auto; margin: 0 auto 5px; border-radius: 2px; object-fit: cover; opacity: .72; }
.finder-post-main { padding-top: 37px; }
.finder-breadcrumb { display: flex; gap: 9px; margin: 0 0 25px; }
.finder-breadcrumb a { color: var(--finder-muted); font-size: 10px; text-decoration: none; }
.finder-breadcrumb a + a::before { margin-right: 9px; content: '/'; color: #c7c3c6; }
.finder-breadcrumb a:hover { color: var(--finder-ink); text-decoration: underline; text-underline-offset: 3px; }
.finder-article { max-width: 100%; }
.finder-article-head { display: flex; gap: 18px; align-items: flex-start; padding: 0 0 24px; border-bottom: 1px solid var(--finder-line); }
.finder-document { position: relative; display: block; flex: 0 0 auto; width: 40px; height: 50px; border: 1px solid #dfbac7; border-radius: 2px; background: #f9e4eb; }
.finder-document::after { position: absolute; top: 8px; left: 8px; width: 22px; height: 1px; background: #d7a8b8; box-shadow: 0 7px 0 #d7a8b8, 0 14px 0 #d7a8b8; content: ''; }
.finder-article-head h1 { margin: 0 0 6px; color: #29272c; font-size: 26px; font-weight: 700; line-height: 1.35; letter-spacing: -.04em; overflow-wrap: anywhere; }
.finder-article-head p { margin: 0; color: var(--finder-muted); font-size: 10px; }
.finder-post-body { max-width: 100%; padding-top: 31px; color: #4c494e; font-size: 13px; line-height: 1.9; overflow-wrap: anywhere; }
.finder-post-body img { max-width: 100%; height: auto; }
.finder-page [hidden] { display: none; }
@media (max-width: 720px) { .finder-page { padding: 18px 13px 28px; } .finder-window { min-height: 0; border-radius: 11px; } .finder-bar { grid-template-columns: 70px minmax(0, 1fr) 70px; min-height: 43px; padding: 0 14px; } .finder-dots { gap: 6px; } .finder-dots span, .finder-back-button, .finder-home-button { width: 9px; height: 9px; } .finder-back-button { font-size: 9px; line-height: 8px; } .finder-bar-actions { gap: 5px; } .finder-owner-links { right: 4px; bottom: 16px; gap: 4px; font-size: 7px; letter-spacing: .04em; } .finder-bar-note { font-size: 7px; } .finder-layout { display: block; min-height: 0; } .finder-sidebar { padding: 18px 15px; border-right: 0; border-bottom: 1px solid var(--finder-line); } .finder-profile { padding-bottom: 16px; } .finder-nav { padding-top: 14px; } .finder-home { display: inline-block; margin: 0 0 9px; } .finder-nav-group { display: grid; grid-template-columns: 82px minmax(0, 1fr); gap: 6px; } .finder-nav-group + .finder-nav-group { margin-top: 8px; } .finder-nav-label { padding: 7px 0 0; } .finder-nav-list { display: flex; flex-wrap: wrap; gap: 0 9px; } .finder-nav-list a { padding: 6px 2px; } .finder-main { padding: 31px 20px 40px; } .finder-home-main { min-height: 360px; } .finder-home-feature { width: min(300px, 100%); } .finder-content-head { margin-bottom: 25px; } .finder-content-head h1 { font-size: 26px; } .finder-count { display: none; } .finder-post-grid, .finder-banner-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 27px 18px; } .finder-banner-grid { grid-template-columns: minmax(0, 1fr); gap: 12px; } .finder-folder { width: 102px; height: 73px; } .finder-banner-card img { width: 80%; height: auto; margin-bottom: 5px; } .finder-post-main { padding-top: 25px; } .finder-breadcrumb { margin-bottom: 19px; } .finder-article-head { gap: 13px; padding-bottom: 19px; } .finder-document { width: 32px; height: 42px; } .finder-document::after { top: 7px; left: 6px; width: 18px; box-shadow: 0 6px 0 #d7a8b8, 0 12px 0 #d7a8b8; } .finder-article-head h1 { font-size: 21px; } .finder-post-body { padding-top: 24px; font-size: 13px; } }
@media (max-width: 720px) { :root[data-imory-post-focus] .finder-sidebar { display: grid; grid-template-rows: 1fr; padding: 0; overflow: hidden; transition: grid-template-rows 340ms cubic-bezier(.32,.72,.24,1), opacity 200ms ease, border-bottom-width 340ms cubic-bezier(.32,.72,.24,1); } :root[data-imory-post-focus] .finder-sidebar-inner { min-height: 0; overflow: hidden; padding: 18px 15px; } :root[data-imory-post-focus="on"] .finder-sidebar { grid-template-rows: 0fr; opacity: 0; border-bottom-width: 0; } :root[data-imory-post-focus="on"] .finder-sidebar-inner { padding-top: 0; padding-bottom: 0; } }
@media (prefers-reduced-motion: reduce) { :root[data-imory-post-focus] .finder-sidebar { transition: none; } }
/* ---- FOLDER-1: category.tree — 폴더 카드 + 자식 글 목록 ---- */
.finder-tree { display: flex; flex-direction: column; gap: 12px; }
.finder-tree:empty::after { padding: 35px 0; color: var(--finder-muted); font-size: 11px; content: '비어 있는 폴더입니다.'; }
.finder-node { min-width: 0; }
.finder-folder-card { position: relative; margin-top: 10px; border: 1px solid #edcbd6; border-radius: 3px 8px 6px 6px; background: #fff; box-shadow: 0 8px 18px rgba(65, 68, 60, .07); }
.finder-folder-card::before { position: absolute; top: -8px; left: -1px; width: 96px; height: 10px; border: 1px solid #edcbd6; border-bottom: 0; border-radius: 6px 8px 0 0; background: var(--finder-pink-deep); content: ''; }
.finder-folder-head { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 11px 16px; border-bottom: 1px solid #edcbd6; border-radius: 2px 7px 0 0; background: var(--finder-pink); box-shadow: inset 0 8px 0 rgba(255,255,255,.17); }
.finder-folder-tab { position: relative; display: block; flex: 0 0 auto; width: 18px; height: 13px; border: 1px solid #dcb3c1; border-radius: 1px 2px 1px 1px; background: #fff8fa; }
.finder-folder-tab::before { position: absolute; top: -4px; left: -1px; width: 8px; height: 4px; border: 1px solid #dcb3c1; border-bottom: 0; border-radius: 2px 3px 0 0; background: #fff8fa; content: ''; }
.finder-folder-name { min-width: 0; color: var(--finder-ink); font-size: 13px; font-weight: 700; letter-spacing: -.01em; overflow-wrap: anywhere; }
.finder-folder-list { margin: 0; padding: 8px 10px 10px; list-style: none; }
.finder-folder-entry { min-width: 0; }
.finder-folder-entry + .finder-folder-entry { border-top: 1px solid #f3e6ea; }
.finder-entry { display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; gap: 10px; min-width: 0; padding: 8px 8px; border-radius: 3px; color: var(--finder-ink); text-decoration: none; }
.finder-entry:hover { background: #fbf2f5; }
.finder-entry:hover .finder-entry-title { text-decoration: underline; text-underline-offset: 3px; }
.finder-entry-doc { position: relative; display: block; width: 12px; height: 15px; border: 1px solid #dfbac7; border-radius: 1px; background: #f9e4eb; }
.finder-entry-doc::after { position: absolute; top: 3px; left: 2px; width: 6px; height: 1px; background: #d7a8b8; box-shadow: 0 3px 0 #d7a8b8, 0 6px 0 #d7a8b8; content: ''; }
.finder-entry-title { min-width: 0; font-size: 12px; font-weight: 500; line-height: 1.45; overflow-wrap: anywhere; }
.finder-entry .finder-lock { margin-top: 0; }
.finder-entry-date { color: var(--finder-muted); font-size: 9px; white-space: nowrap; }
.finder-root-entry { border: 1px solid var(--finder-line); background: var(--finder-paper); padding: 10px 12px; }
.finder-root-entry:hover { background: #fbf2f5; }
.finder-subfolder { margin: 4px 0 6px; padding-left: 10px; border-left: 2px solid var(--finder-pink-deep); }
.finder-subfolder-name { display: flex; align-items: center; gap: 8px; min-width: 0; margin: 0; padding: 6px 6px; color: #8f6f7b; font-size: 11px; font-weight: 700; overflow-wrap: anywhere; }
.finder-subfolder-mark { position: relative; display: block; flex: 0 0 auto; width: 14px; height: 10px; border: 1px solid #edcbd6; border-radius: 1px 3px 1px 1px; background: var(--finder-pink); }
.finder-subfolder-mark::before { position: absolute; top: -3px; left: -1px; width: 6px; height: 3px; border: 1px solid #edcbd6; border-bottom: 0; border-radius: 2px 2px 0 0; background: var(--finder-pink-deep); content: ''; }
.finder-subfolder .finder-folder-list { padding: 0 0 4px 4px; }
@media (max-width: 720px) { .finder-folder-head { padding: 10px 12px; } .finder-folder-list { padding: 6px 6px 8px; } .finder-entry { grid-template-columns: auto minmax(0, 1fr) auto; gap: 4px 8px; padding: 8px 6px; } .finder-entry-date { grid-column: 2 / -1; grid-row: 2; } .finder-root-entry { padding: 9px 10px; } }

/* ---- FOLDER-2: 폴더 OPEN 링크 + 폴더 페이지(Series Viewer) ---- */
.finder-folder-open { margin-left: auto; flex: 0 0 auto; padding: 2px 7px; border: 1px solid #dcb3c1; border-radius: 2px; background: #fff8fa; color: #8f6f7b; font-size: 8px; letter-spacing: .1em; text-decoration: none; }
.finder-folder-open:hover { background: #f2cbd8; color: var(--finder-ink); }
.finder-subfolder-open { margin-left: auto; }
.finder-folder-main { padding-top: 37px; }
.finder-series-head { align-items: end; margin-bottom: 22px; }
.finder-series-children { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 26px; }
.finder-series-child { display: inline-flex; align-items: center; gap: 7px; padding: 5px 9px; border: 1px solid #edcbd6; border-radius: 3px; background: #fff; color: #8f6f7b; font-size: 11px; font-weight: 700; text-decoration: none; }
.finder-series-child:hover { background: #fbf2f5; }
.finder-series-child-count { color: var(--finder-muted); font-size: 9px; font-weight: 400; }
.finder-series { display: flex; flex-direction: column; }
.finder-series-post { min-width: 0; }
.finder-series-post + .finder-series-post { margin-top: 34px; padding-top: 30px; border-top: 1px dashed #e4d3d9; }
.finder-series-post-head { display: flex; align-items: flex-start; gap: 12px; }
.finder-series-post-head .finder-entry-doc { margin-top: 5px; }
.finder-series-post-head > div { min-width: 0; flex: 1 1 auto; }
.finder-series-post-title { margin: 0 0 3px; color: #29272c; font-size: 19px; font-weight: 700; line-height: 1.35; letter-spacing: -.03em; overflow-wrap: anywhere; }
.finder-series-post-date { margin: 0; color: var(--finder-muted); font-size: 10px; }
.finder-series-post-edit { flex: 0 0 auto; color: var(--finder-muted); font-size: 9px; letter-spacing: .09em; text-decoration: none; }
.finder-series-post-edit:hover { color: var(--finder-ink); text-decoration: underline; text-underline-offset: 3px; }
.finder-series-post .finder-post-body { padding-top: 16px; }
.finder-series-post .post-secret-gate { margin: 8px 0 0; }
.finder-series-foot { margin: 40px 0 0; padding-top: 18px; border-top: 1px solid var(--finder-line); }
.finder-series-foot a { color: var(--finder-muted); font-size: 10px; letter-spacing: .08em; text-decoration: none; }
.finder-series-foot a:hover { color: var(--finder-ink); text-decoration: underline; text-underline-offset: 3px; }
@media (max-width: 720px) { .finder-folder-main { padding-top: 24px; } .finder-series-post + .finder-series-post { margin-top: 26px; padding-top: 22px; } .finder-series-post-title { font-size: 16px; } }
